"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 probe pilot (docs/iterations.md, 2026-11-19; approved by the author). Exploratory, local, no API;
dev for evaluation only, test untouched.

Question: does our main model (L1: frozen VoxTurn, whose ears are the Qwen3-ASR-0.6B AuT encoder, plus our LoRA on the
language model and the option head) internally hear whether a real phone, doorbell or knock is in the 8 s window,
even where its decision follows the detector's label instead?

Design, fixed in the log before running:
- Points: R-hear points (the respond question; the three versions of a unit share the line, only the sound differs:
  version 1 a real phone, doorbell or knock, version 2 no event, version 3 a household decoy). Target: a real phone,
  doorbell or knock clip in the window (p1v4_data.window_events), as in the trust curves.
- Read-outs (one forward pass, the model as scored on dev: both adapters, phrasing 0):
  - ears: the audio tokens the language model receives (AuT encoder + VoxTurn projector, 104 tokens), mean and max
    over time; text-free, so the same in every label condition;
  - decision side: the language model's hidden states at the respond question's two option positions (the head's
    read-out positions), concatenated, after layers 4, 8, 12, 16, 20, 24 and 28 (the last).
- Training inputs (train split, all R-hear points, seed 0): the event labels are made independent of the truth, so
  a probe cannot read the label instead of the sound:
  - version 1 (real): half keep their phone/doorbell/knock detections with one confidence drawn from U(0.3, 1.0),
    half have them removed;
  - versions 2 and 3 (no event): half keep their natural labels, half get one false label (phone, doorbell or knock
    at random, confidence U(0.3, 1.0), placed as in the injection pilot: ending 0.3-1.5 s before the line, 1.5-3.0 s
    long; points without 0.5 s of room keep their natural labels).
- Probes: standardised features, logistic regression; the regularisation strength (C in 0.001, 0.01, 0.1, 1) and the
  layer chosen by 5-fold cross-validation on train grouped by unit (AUC); then fitted on all of train.
- Dev evaluation (three inputs of every dev R-hear point, excluded units left out as in scoring):
  - natural: the dev inputs as scored; primary subset = points with a phone/doorbell/knock label of confidence
    0.5-0.9 (the trust-curve subset: 24 real, 51 false);
  - injected: the injection pilot's false phone label at every no-event point (data/p1v4/runs/inject_pilot);
  - removed: every phone/doorbell/knock detection removed.
  Reported: AUC with a 95% bootstrap interval (2,000 resamples of points) for the ears probe and the chosen layer,
  every layer's AUC, and on the same subsets the AUC of the model's own decision (1 - P(respond)), of the label
  confidence, and of L3's decision. Check: the natural pass reproduces the stored dev scores of L1.
- Verdict, on the primary subset, by the better of the ears probe and the chosen layer: AUC >= 0.90 the model hears
  (go to step 2, a runtime conflict monitor and correction); 0.75-0.90 partly; below 0.75 it does not (then train the
  listening side).
usage (repo root):
  .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_probe_pilot.py extract train
  .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_probe_pilot.py extract dev
  .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_probe_pilot.py fit
Outputs: data/p1v4/runs/probe_pilot/feats_{train,dev}.npz, results/main_v04/probe_pilot_dev.json.
"""
import json
import os
import random
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_score as S  # noqa: E402

R = "data/p1v4/runs"
OUT = f"{R}/probe_pilot"
EVENT = ("phone", "doorbell", "knock")
LAYERS = (4, 8, 12, 16, 20, 24, 28)
CS = (0.001, 0.01, 0.1, 1.0)
SEED = 0


def keyed(d):
    return {(k.split("|")[0], k.split("|")[1], int(k.split("|")[2])): v for k, v in d.items()}


def is_real(r, t):
    return any(c in EVENT for c, _, _ in D.window_events(r, t))


def false_span(r, p, rng):
    """As the injection pilot: ends 0.3-1.5 s before the line (or the point), 1.5-3.0 s long, inside the window."""
    src = {s["id"]: s for s in r["sources"]}
    t = p["t"]
    ls = src[p["line"]]["start"] if p.get("line") else t
    s1 = ls - rng.uniform(0.3, 1.5)
    s0 = max(s1 - rng.uniform(1.5, 3.0), t - D.WIN_S + 0.01)
    return (round(s0, 2), round(s1, 2)) if s1 - s0 >= 0.5 else None


class Edited(C.Context):
    """A context whose sound lists are edited per point: {pid: ("drop",) | ("conf", c) | ("add", cls, s0, s1, c)}."""

    def __init__(self, which, edits):
        super().__init__(which)
        self.edits = edits

    def point(self, r, k):
        tr, sc, tags, snd = super().point(r, k)
        e = self.edits.get(self.pid(r, k))
        if e:
            if e[0] == "drop":
                snd = [s for s in snd if s[0] not in EVENT]
            elif e[0] == "conf":
                snd = [(s[0], s[1], s[2], e[1]) if s[0] in EVENT else s for s in snd]
            elif e[0] == "add":
                snd = sorted(list(snd) + [tuple(e[1:])], key=lambda s: (s[1], s[0]))
        return tr, sc, tags, snd


def r_hear_points(rows):
    return [(r, p) for r in rows if r["part"] == "r_hear" for p in r["points"]]


def train_edits(rows):
    rng = random.Random(SEED)
    edits, cond = {}, {}
    for r, p in r_hear_points(rows):
        pid = f"{r['unit']}|{r['version']}|{p['k']}"
        if is_real(r, p["t"]):
            if rng.random() < 0.5:
                edits[pid], cond[pid] = ("conf", round(rng.uniform(0.3, 1.0), 3)), "real, label kept"
            else:
                edits[pid], cond[pid] = ("drop",), "real, label removed"
        else:
            span = false_span(r, p, rng)
            if rng.random() < 0.5 and span:
                edits[pid] = ("add", rng.choice(EVENT), span[0], span[1], round(rng.uniform(0.3, 1.0), 3))
                cond[pid] = "no event, false label"
            else:
                cond[pid] = "no event, natural labels"
    return edits, cond


def dev_edits(rows, which):
    if which == "natural":
        return {}
    if which == "removed":
        return {f"{r['unit']}|{r['version']}|{p['k']}": ("drop",) for r, p in r_hear_points(rows)}
    inj = json.load(open(f"{R}/inject_pilot/injections.json"))
    out = {}
    for r, p in r_hear_points(rows):
        pid = f"{r['unit']}|{r['version']}|{p['k']}"
        if pid in inj:
            out[pid] = ("add", *inj[pid])
    return out


# ------------------------------------------------------------------------------------------------ extraction

def forward_feats(model, waves, texts, markers):
    """Ears (mean and max of the audio tokens), hidden states at the respond options for LAYERS, and P(respond)."""
    import torch
    import torch.nn as nn
    import torch.nn.functional as F
    import p1v4_l1 as L1
    vt, mod = model.vt, model.mod
    dev = vt.head.weight.device
    emb = vt.llm.get_input_embeddings()
    with torch.no_grad(), torch.autocast("cuda", dtype=torch.bfloat16):
        audio = vt.encode_audio(vt.mel(waves))
        seqs, opt_pos = [], []
        q_ids, q_pos = vt.prompt("respond", "en", 0)
        for b in range(len(texts)):
            ids = vt.context_ids(texts[b], markers[b], "en", L1.MAX_TEXT_TOKENS)
            prefix = torch.cat([emb(torch.tensor(vt.seq_head + vt.audio_open, device=dev)), audio[b],
                                emb(torch.tensor(vt.audio_close + ids, device=dev))], 0)
            opt_pos.append([len(prefix) + p for p in q_pos])
            seqs.append(torch.cat([prefix, emb(torch.tensor(q_ids, device=dev))], 0))
        x = nn.utils.rnn.pad_sequence(seqs, batch_first=True)
        x = F.pad(x, (0, 0, 0, -x.shape[1] % mod.LEN_BUCKET))
        out = vt.llm(inputs_embeds=x, output_hidden_states=True)
        hs = out.hidden_states
        assert len(hs) == 29, len(hs)
        b_idx = torch.arange(len(texts), device=dev)[:, None]
        pos = torch.tensor(opt_pos, device=dev)
        layers = [hs[l][b_idx, pos].float().reshape(len(texts), -1) for l in LAYERS]
        last = out.last_hidden_state[b_idx, pos].float()
    with torch.no_grad():                            # the head outside autocast, as L1v4.forward
        p_resp = model.new_head(last).squeeze(-1).softmax(-1)[:, 1]
    a = audio.float()
    ears = torch.cat([a.mean(1), a.amax(1)], -1)
    return ears.cpu().numpy(), np.stack([l.cpu().numpy() for l in layers], 1), p_resp.cpu().numpy()


def extract(which):
    import soundfile as sf
    import torch
    import p1v4_l1 as L1
    D.gpu_guard()
    os.makedirs(OUT, exist_ok=True)
    rows = D.load_rows(which)
    pts = r_hear_points(rows)
    conds = {"train": ["train"], "dev": ["natural", "injected", "removed"]}[which]
    model = L1.build()
    L1.load_new_state(model, torch.load(f"{R}/l1/l1_new.pt", weights_only=True))
    model.eval()
    res = {}
    for cond in conds:
        if cond == "train":
            edits, labels = train_edits(rows)
        else:
            edits = dev_edits(rows, cond)
            labels = {pid: "edited" for pid in edits}
        ctx = Edited(which, edits)
        items = []
        for r, p in pts:
            text, asks = ctx.situation(r, p["k"], "full")
            assert [a[0] for a in asks] == ["R"], asks
            snd = [s for s in ctx.point(r, p["k"])[3] if s[0] in EVENT and s[1] < p["t"]]
            items.append({"id": f"{r['unit']}|{r['version']}|{p['k']}", "unit": r["unit"], "path": p["window"],
                          "text": text, "marker": "agent" if p.get("assistant_speaking") else "user",
                          "real": is_real(r, p["t"]), "conf": max([s[3] for s in snd], default=-1.0)})
        ears, hid, presp = [], [], []
        t0 = time.time()
        B = 8
        for i in range(0, len(items), B):
            chunk = items[i:i + B]
            waves = torch.stack([torch.from_numpy(sf.read(it["path"], dtype="float32")[0]) for it in chunk]).cuda()
            e, h, pr = forward_feats(model, waves, [it["text"] for it in chunk], [it["marker"] for it in chunk])
            ears.append(e.astype(np.float16))
            hid.append(h.astype(np.float16))
            presp.append(pr)
            if (i // B) % 100 == 0:
                print(f"{which}/{cond}: {i + len(chunk)}/{len(items)} {time.time() - t0:.0f} s", flush=True)
        res[cond] = {"ids": np.array([it["id"] for it in items]), "units": np.array([it["unit"] for it in items]),
                     "real": np.array([it["real"] for it in items]), "conf": np.array([it["conf"] for it in items]),
                     "cond": np.array([labels.get(it["id"], "unedited") for it in items]),
                     "ears": np.concatenate(ears), "hid": np.concatenate(hid), "p_respond": np.concatenate(presp)}
        print(f"{which}/{cond} done: {len(items)} points, {time.time() - t0:.0f} s", flush=True)
    np.savez(f"{OUT}/feats_{which}.npz", **{f"{c}__{k}": v for c, d in res.items() for k, v in d.items()})
    if which == "dev":
        stored = keyed(json.load(open(f"{R}/l1/scores_dev.json")))
        d = res["natural"]
        diff = [abs(stored[tuple(i.split("|")[:2]) + (int(i.split("|")[2]),)]["R"] - p)
                for i, p in zip(d["ids"], d["p_respond"])]
        print(f"check vs stored L1 dev scores: max |diff| {max(diff):.4f}, median {np.median(diff):.5f}")


# ------------------------------------------------------------------------------------------------ probes

def load(which):
    z = np.load(f"{OUT}/feats_{which}.npz")
    out = {}
    for k in z.files:
        c, f = k.split("__")
        out.setdefault(c, {})[f] = z[k]
    return out


def auc(y, s):
    from sklearn.metrics import roc_auc_score
    y = np.asarray(y, bool)
    return float(roc_auc_score(y, s)) if 0 < y.sum() < len(y) else None


def auc_ci(y, s, B=2000, seed=1):
    rng = np.random.default_rng(seed)
    y, s = np.asarray(y, bool), np.asarray(s, float)
    vals = []
    for _ in range(B):
        i = rng.integers(0, len(y), len(y))
        a = auc(y[i], s[i])
        if a is not None:
            vals.append(a)
    return [float(np.percentile(vals, 2.5)), float(np.percentile(vals, 97.5))]


def fit_probe(X, y, groups):
    """C chosen by grouped 5-fold CV AUC (the scaler is fitted on all of train first, a negligible leak for a
    pilot); returns (cv auc, C, fitted pipeline refitted on all of train)."""
    from sklearn.linear_model import LogisticRegressionCV
    from sklearn.model_selection import GroupKFold
    from sklearn.pipeline import make_pipeline
    from sklearn.preprocessing import StandardScaler
    folds = list(GroupKFold(5).split(X, y, groups))
    m = make_pipeline(StandardScaler(), LogisticRegressionCV(Cs=list(CS), cv=folds, scoring="roc_auc", max_iter=3000,
                                                             n_jobs=4))
    m.fit(X, y)
    lr = m[-1]
    return float(lr.scores_[1].mean(axis=0).max()), float(lr.C_[0]), m


def fit():
    tr = load("train")["train"]
    dv = load("dev")
    ex = S.excluded_units()
    keep = {c: np.array([u not in ex for u in d["units"]]) for c, d in dv.items()}
    y_tr, g_tr = tr["real"].astype(int), tr["units"]
    feats_tr = {"ears": tr["ears"].astype(np.float32)}
    feats_tr.update({f"layer {l}": tr["hid"][:, i].astype(np.float32) for i, l in enumerate(LAYERS)})
    probes = {}
    for name, X in feats_tr.items():
        cv, c, m = fit_probe(X, y_tr, g_tr)
        probes[name] = {"cv_auc": cv, "C": c, "model": m}
        print(f"{name:9s} train CV AUC {cv:.3f} (C {c})", flush=True)
    best_layer = max((n for n in probes if n != "ears"), key=lambda n: probes[n]["cv_auc"])
    l3 = keyed(json.load(open(f"{R}/l3/scores_dev.json")))
    res = {"layers": list(LAYERS), "train_cv": {n: {"auc": p["cv_auc"], "C": p["C"]} for n, p in probes.items()},
           "chosen_layer": best_layer, "train_conditions": {k: int(v) for k, v in
                                                            zip(*np.unique(tr["cond"], return_counts=True))},
           "dev": {}}
    for cond, d in dv.items():
        k = keep[cond]
        y = d["real"][k]
        sub = {"all": np.ones(k.sum(), bool)}
        if cond == "natural":
            sub["primary: label 0.5-0.9"] = (d["conf"][k] >= 0.5) & (d["conf"][k] < 0.9)
        if cond == "injected":
            sub["injected false vs real"] = y | (d["cond"][k] == "edited")
        out = {}
        for sname, s in sub.items():
            ys = y[s]
            row = {"n_real": int(ys.sum()), "n_not": int((~ys).sum())}
            for name, p in probes.items():
                X = (d["ears"] if name == "ears" else d["hid"][:, LAYERS.index(int(name.split()[1]))])[k][s]
                sc = p["model"].predict_proba(X.astype(np.float32))[:, 1]
                row[name] = auc(ys, sc)
                if name in ("ears", best_layer):
                    row[f"{name} ci95"] = auc_ci(ys, sc)
                    thr = 0.5
                    row[f"{name} at 0.5"] = {"real heard": f"{int((sc[ys] >= thr).sum())}/{int(ys.sum())}",
                                             "false heard": f"{int((sc[~ys] >= thr).sum())}/{int((~ys).sum())}"}
            row["model decision (1 - P(respond))"] = auc(ys, 1 - d["p_respond"][k][s])
            row["label confidence"] = auc(ys, np.maximum(d["conf"][k][s], 0))
            if cond == "natural":
                l3s = np.array([1 - l3[tuple(i.split("|")[:2]) + (int(i.split("|")[2]),)]["R"]
                                for i in d["ids"][k][s]])
                row["L3 decision (1 - P(respond))"] = auc(ys, l3s)
            out[sname] = row
        res["dev"][cond] = out
    prim = res["dev"]["natural"]["primary: label 0.5-0.9"]
    best = max(prim["ears"] or 0, prim[best_layer] or 0)
    res["verdict"] = {"auc_used": best, "by": "ears" if (prim["ears"] or 0) >= (prim[best_layer] or 0) else best_layer,
                      "reading": "hears (go to step 2)" if best >= 0.90 else "partly (0.75-0.90)" if best >= 0.75
                      else "does not hear (train the listening side)"}
    json.dump(res, open("results/main_v04/probe_pilot_dev.json", "w"), indent=1)
    print(json.dumps({k: v for k, v in res.items() if k != "dev"}, indent=1))
    for cond, out in res["dev"].items():
        for sname, row in out.items():
            print(f"[{cond} / {sname}] " + json.dumps(row))


if __name__ == "__main__":
    if sys.argv[1] == "extract":
        extract(sys.argv[2])
    elif sys.argv[1] == "fit":
        fit()
    else:
        raise SystemExit(__doc__)
